-- ============================================================================
-- kaggle_seed.sql — Sinh tự động bởi db/kaggle_dataset/build_kaggle_csvs.js
-- Dữ liệu chuẩn hóa từ 3 bộ Kaggle công khai thật:
--   1) seatransport/southeast-asia-transport-data (ODbL 1.0)
--   2) rohitgds/pan-india-bus-routes-35k-schedules-1000-cities (CC BY 4.0)
--   3) iamvijay7/bus-journey-demand-forecasting-dataset (CC0)
-- Tương thích 100% với db/01_init_schema.sql và db/02_seed_data.sql (Idempotent)
-- ============================================================================
BEGIN;

-- 1. Users (Mật khẩu mẫu: 123456)

-- 2. Stations (Bến xe Việt Nam từ Kaggle GeoJSON OpenStreetMap)

-- 3. Routes (32 tuyến liên tỉnh Việt Nam từ Kaggle GeoJSON)

-- 4. Seat Layouts (4 sơ đồ ghế chuẩn hóa từ Kaggle Pan-India_Bus_Routes.csv)

-- 5. Buses (12 xe khách)

-- 6. Articles (8 bài viết đủ 4 chuyên mục)

-- 7. Trips (Lịch chạy xe khách theo khung giờ thực tế Kaggle)

-- 8. Trip Stops (Điểm đón/trả tự động gán cho mọi chuyến xe chưa có điểm dừng)

-- 9 & 10. Bookings & Tickets (Đơn đặt vé + Vé ghế điện tử từ nhu cầu Kaggle)
WITH target_trip AS (  SELECT t.id FROM trips t JOIN routes r ON t.route_id = r.id JOIN buses b ON t.bus_id = b.id   WHERE LOWER(r.name) = LOWER('TP. Hồ Chí Minh - Đà Lạt') AND b.license_plate = '51B-289.01'   ORDER BY ABS(EXTRACT(EPOCH FROM (t.departure_time - (CURRENT_DATE + INTERVAL '1 days' + INTERVAL '1260 minutes')))) ASC LIMIT 1), ins_booking AS (  INSERT INTO bookings (booking_code, user_id, trip_id, pickup_stop_id, dropoff_stop_id, passenger_name, passenger_phone, passenger_email, seat_count, total_amount, status, hold_expires_at, refund_amount)   SELECT 'BT2601', u.id, tt.id,     (SELECT id FROM trip_stops WHERE trip_id = tt.id AND stop_type = 'pickup' ORDER BY stop_order ASC LIMIT 1),     (SELECT id FROM trip_stops WHERE trip_id = tt.id AND stop_type = 'dropoff' ORDER BY stop_order DESC LIMIT 1),     'Nguyễn Văn Khách', '0912345678', 'khach1@gmail.com',     2, 680000, 'pending',     NOW() + INTERVAL '10 minutes', 0   FROM target_trip tt LEFT JOIN users u ON LOWER(u.email) = LOWER('khach1@gmail.com')   ON CONFLICT (booking_code) DO NOTHING RETURNING id, trip_id) INSERT INTO tickets (booking_id, trip_id, seat_code, ticket_code, price, status, checked_in_at) SELECT ib.id, ib.trip_id, sc.seat_code, 'TK-' || 'BT2601' || '-' || sc.seat_code, 340000, 'held', NULL FROM ins_booking ib CROSS JOIN (VALUES ('A01'), ('A02')) AS sc(seat_code) WHERE NOT EXISTS (  SELECT 1 FROM tickets tk WHERE tk.trip_id = ib.trip_id AND tk.seat_code = sc.seat_code     AND tk.status IN ('held', 'paid', 'checked_in') AND 'held' IN ('held', 'paid', 'checked_in')) ON CONFLICT (ticket_code) DO NOTHING;
WITH target_trip AS (  SELECT t.id FROM trips t JOIN routes r ON t.route_id = r.id JOIN buses b ON t.bus_id = b.id   WHERE LOWER(r.name) = LOWER('TP. Hồ Chí Minh - Đà Lạt') AND b.license_plate = '51B-289.01'   ORDER BY ABS(EXTRACT(EPOCH FROM (t.departure_time - (CURRENT_DATE + INTERVAL '1 days' + INTERVAL '1260 minutes')))) ASC LIMIT 1), ins_booking AS (  INSERT INTO bookings (booking_code, user_id, trip_id, pickup_stop_id, dropoff_stop_id, passenger_name, passenger_phone, passenger_email, seat_count, total_amount, status, hold_expires_at, refund_amount)   SELECT 'BT2602', u.id, tt.id,     (SELECT id FROM trip_stops WHERE trip_id = tt.id AND stop_type = 'pickup' ORDER BY stop_order ASC LIMIT 1),     (SELECT id FROM trip_stops WHERE trip_id = tt.id AND stop_type = 'dropoff' ORDER BY stop_order DESC LIMIT 1),     'Nguyễn Văn Khách', '0912345678', 'khach1@gmail.com',     2, 680000, 'paid',     NULL, 0   FROM target_trip tt LEFT JOIN users u ON LOWER(u.email) = LOWER('khach1@gmail.com')   ON CONFLICT (booking_code) DO NOTHING RETURNING id, trip_id) INSERT INTO tickets (booking_id, trip_id, seat_code, ticket_code, price, status, checked_in_at) SELECT ib.id, ib.trip_id, sc.seat_code, 'TK-' || 'BT2602' || '-' || sc.seat_code, 340000, 'paid', NULL FROM ins_booking ib CROSS JOIN (VALUES ('A03'), ('A04')) AS sc(seat_code) WHERE NOT EXISTS (  SELECT 1 FROM tickets tk WHERE tk.trip_id = ib.trip_id AND tk.seat_code = sc.seat_code     AND tk.status IN ('held', 'paid', 'checked_in') AND 'paid' IN ('held', 'paid', 'checked_in')) ON CONFLICT (ticket_code) DO NOTHING;
WITH target_trip AS (  SELECT t.id FROM trips t JOIN routes r ON t.route_id = r.id JOIN buses b ON t.bus_id = b.id   WHERE LOWER(r.name) = LOWER('TP. Hồ Chí Minh - Đà Lạt') AND b.license_plate = '51B-289.01'   ORDER BY ABS(EXTRACT(EPOCH FROM (t.departure_time - (date_trunc('minute', NOW() + INTERVAL '6 hours'))))) ASC LIMIT 1), ins_booking AS (  INSERT INTO bookings (booking_code, user_id, trip_id, pickup_stop_id, dropoff_stop_id, passenger_name, passenger_phone, passenger_email, seat_count, total_amount, status, hold_expires_at, refund_amount)   SELECT 'BT2603', u.id, tt.id,     (SELECT id FROM trip_stops WHERE trip_id = tt.id AND stop_type = 'pickup' ORDER BY stop_order ASC LIMIT 1),     (SELECT id FROM trip_stops WHERE trip_id = tt.id AND stop_type = 'dropoff' ORDER BY stop_order DESC LIMIT 1),     'Nguyễn Văn Khách', '0912345678', 'khach1@gmail.com',     1, 330000, 'paid',     NULL, 0   FROM target_trip tt LEFT JOIN users u ON LOWER(u.email) = LOWER('khach1@gmail.com')   ON CONFLICT (booking_code) DO NOTHING RETURNING id, trip_id) INSERT INTO tickets (booking_id, trip_id, seat_code, ticket_code, price, status, checked_in_at) SELECT ib.id, ib.trip_id, sc.seat_code, 'TK-' || 'BT2603' || '-' || sc.seat_code, 330000, 'paid', NULL FROM ins_booking ib CROSS JOIN (VALUES ('B01')) AS sc(seat_code) WHERE NOT EXISTS (  SELECT 1 FROM tickets tk WHERE tk.trip_id = ib.trip_id AND tk.seat_code = sc.seat_code     AND tk.status IN ('held', 'paid', 'checked_in') AND 'paid' IN ('held', 'paid', 'checked_in')) ON CONFLICT (ticket_code) DO NOTHING;
WITH target_trip AS (  SELECT t.id FROM trips t JOIN routes r ON t.route_id = r.id JOIN buses b ON t.bus_id = b.id   WHERE LOWER(r.name) = LOWER('TP. Hồ Chí Minh - Nha Trang') AND b.license_plate = '51B-289.02'   ORDER BY ABS(EXTRACT(EPOCH FROM (t.departure_time - (CURRENT_DATE + INTERVAL '2 days' + INTERVAL '1200 minutes')))) ASC LIMIT 1), ins_booking AS (  INSERT INTO bookings (booking_code, user_id, trip_id, pickup_stop_id, dropoff_stop_id, passenger_name, passenger_phone, passenger_email, seat_count, total_amount, status, hold_expires_at, refund_amount)   SELECT 'BT2604', u.id, tt.id,     (SELECT id FROM trip_stops WHERE trip_id = tt.id AND stop_type = 'pickup' ORDER BY stop_order ASC LIMIT 1),     (SELECT id FROM trip_stops WHERE trip_id = tt.id AND stop_type = 'dropoff' ORDER BY stop_order DESC LIMIT 1),     'Nguyễn Văn Khách', '0912345678', 'khach1@gmail.com',     1, 480000, 'checked_in',     NULL, 0   FROM target_trip tt LEFT JOIN users u ON LOWER(u.email) = LOWER('khach1@gmail.com')   ON CONFLICT (booking_code) DO NOTHING RETURNING id, trip_id) INSERT INTO tickets (booking_id, trip_id, seat_code, ticket_code, price, status, checked_in_at) SELECT ib.id, ib.trip_id, sc.seat_code, 'TK-' || 'BT2604' || '-' || sc.seat_code, 480000, 'checked_in', NOW() FROM ins_booking ib CROSS JOIN (VALUES ('A05')) AS sc(seat_code) WHERE NOT EXISTS (  SELECT 1 FROM tickets tk WHERE tk.trip_id = ib.trip_id AND tk.seat_code = sc.seat_code     AND tk.status IN ('held', 'paid', 'checked_in') AND 'checked_in' IN ('held', 'paid', 'checked_in')) ON CONFLICT (ticket_code) DO NOTHING;
