INSERT INTO articles (title, slug, category, summary, content, is_published) VALUES ('Khuyến mãi mở tuyến Cao tốc TP.HCM - Phan Thiết - Nha Trang', 'khuyen-mai-cao-toc-nha-trang', 'promotion', 'Giảm ngay 15% giá vé cho hành khách đặt vé trực tuyến sớm trước 3 ngày trên mạng lưới 32 tuyến liên tỉnh.', 'Áp dụng cho toàn bộ chuyến xe giường nằm Limousine và Volvo Multi-Axle trên tuyến TP. Hồ Chí Minh - Phan Thiết và TP. Hồ Chí Minh - Nha Trang.', TRUE) ON CONFLICT (slug) DO NOTHING;
INSERT INTO articles (title, slug, category, summary, content, is_published) VALUES ('Chính sách hoàn vé và hủy vé trực tuyến', 'chinh-sach-hoan-huy-ve', 'policy', 'Quy định hủy vé trước 24 giờ khởi hành và hoàn tiền 100% khi nhà xe hủy chuyến.', 'Hành khách được hủy vé trực tuyến trước giờ khởi hành tối thiểu 24 giờ đối với đơn đã thanh toán (paid) hoặc hủy ngay khi đơn đang chờ thanh toán (pending).', TRUE) ON CONFLICT (slug) DO NOTHING;
INSERT INTO articles (title, slug, category, summary, content, is_published) VALUES ('Hướng dẫn giữ ghế 10 phút và nhận vé điện tử QR qua Email', 'huong-dan-giu-ghe-va-nhan-ve-qr', 'faq', 'Giải đáp cơ chế khóa ghế tạm thời 10 phút bằng Unique Partial Index chống trùng ghế.', 'Sau khi chọn ghế trên sơ đồ trực quan, hệ thống khóa tạm ghế trong 10 phút. Quá 10 phút chưa thanh toán, hệ thống tự động chuyển trạng thái expired và mở lại ghế.', TRUE) ON CONFLICT (slug) DO NOTHING;
INSERT INTO articles (title, slug, category, summary, content, is_published) VALUES ('Cập nhật mạng lưới 32 tuyến xe khách liên tỉnh Việt Nam từ dữ liệu mở OpenStreetMap & Kaggle', 'mang-luoi-tuyen-xe-khach-lien-tinh-viet-nam-kaggle', 'news', 'Kết nối 31 bến xe từ Hà Nội, Sa Pa, Hạ Long, Đà Nẵng đến TP.HCM, Đà Lạt, Nha Trang, Cần Thơ, Hà Tiên.', 'Dữ liệu mạng lưới tuyến xe liên tỉnh được chuẩn hóa trực tiếp từ bộ dữ liệu mở Kaggle seatransport/southeast-asia-transport-data (cập nhật 2026-11-19, giấy phép ODbL-1.0) với tọa độ thực tế từng địa phương.', TRUE) ON CONFLICT (slug) DO NOTHING;
INSERT INTO articles (title, slug, category, summary, content, is_published) VALUES ('Thông tin 19 cửa khẩu đường bộ e-Visa kết nối tuyến xe khách quốc tế Việt Nam', 'thong-tin-cua-khau-duong-bo-evisa-viet-nam', 'news', 'Tổng hợp 19 cửa khẩu đường bộ đang mở (Lào Cai ↔ Hekou, Hữu Nghị ↔ Youyiguan, Đồng Đăng ↔ Pingxiang (rail), Móng Cái ↔ Dongxing, Tây Trang ↔ Pang Hok, Lóng Sập ↔ Pa Hang...) từ dữ liệu Kaggle vietnam-border-crossings.csv.', 'Theo tệp vietnam-border-crossings.csv (Kaggle seatransport/southeast-asia-transport-data), Việt Nam có 19 cửa khẩu đường bộ chấp nhận e-Visa kết nối đi Lào, Campuchia và Trung Quốc.', TRUE) ON CONFLICT (slug) DO NOTHING;
INSERT INTO articles (title, slug, category, summary, content, is_published) VALUES ('Ra mắt đội xe Volvo B9R Multi-Axle & Limousine 22 Phòng Đôi VIP', 'ra-mat-doi-xe-volvo-multi-axle-limousine', 'news', 'Nâng cấp đội xe đường dài theo tiêu chuẩn vận hành liên tỉnh với hệ thống giảm xóc khí nén Air Suspension.', 'Các cấu hình xe Volvo Multi-Axle Semi-Sleeper 36 chỗ và Limousine 22 phòng đôi được bố trí trên các tuyến đường dài trên 250km như TP.HCM - Đà Lạt, TP.HCM - Nha Trang và Hà Nội - Sa Pa.', TRUE) ON CONFLICT (slug) DO NOTHING;
INSERT INTO articles (title, slug, category, summary, content, is_published) VALUES ('Quy định hành lý ký gửi và thời gian có mặt tại bến xe', 'quy-dinh-hanh-ly-ky-gui-lien-tinh', 'policy', 'Mỗi hành khách được miễn phí 20kg hành lý ký gửi và cần có mặt trước giờ khởi hành 30 phút.', 'Hành khách xuất trình mã QR vé điện tử cho nhân viên soát vé (Staff Check-in) trước khi lên xe tối thiểu 15-30 phút tại điểm đón đã chọn.', TRUE) ON CONFLICT (slug) DO NOTHING;
INSERT INTO articles (title, slug, category, summary, content, is_published) VALUES ('Câu hỏi thường gặp về chọn điểm đón/trả dọc tuyến (Trip Stops)', 'faq-diem-don-tra-doc-tuyen', 'faq', 'Hướng dẫn chọn điểm đón (VP Hàng Xanh, Bến xe Miền Đông Mới) và điểm trả trung gian (Bảo Lộc, Phan Thiết).', 'Mỗi chuyến xe đều niêm yết rõ danh sách điểm đón (pickup) và điểm trả (dropoff) theo thứ tự stop_order kèm giờ dự kiến để hành khách chủ động di chuyển.', TRUE) ON CONFLICT (slug) DO NOTHING;
INSERT INTO trips (route_id, bus_id, departure_time, arrival_time, ticket_price, status) SELECT r.id, b.id, date_trunc('minute', NOW() + INTERVAL '6 hours'), (date_trunc('minute', NOW() + INTERVAL '6 hours')) + INTERVAL '390 minutes', 330000, 'active' FROM (SELECT id FROM routes WHERE LOWER(name) = LOWER('TP. Hồ Chí Minh - Đà Lạt') ORDER BY id ASC LIMIT 1) r JOIN (SELECT id FROM buses WHERE license_plate = '51B-289.01' LIMIT 1) b ON TRUE WHERE NOT EXISTS (  SELECT 1 FROM trips t WHERE t.route_id = r.id AND t.bus_id = b.id     AND ABS(EXTRACT(EPOCH FROM (t.departure_time - (date_trunc('minute', NOW() + INTERVAL '6 hours'))))) < 1800);
