INSERT INTO trip_stops (trip_id, station_id, stop_type, stop_time, stop_order) SELECT t.id, s.id, 'pickup', t.departure_time + INTERVAL '-30 minutes', 1 FROM trips t JOIN routes r ON t.route_id = r.id JOIN (SELECT id FROM stations WHERE LOWER(name) = LOWER('VP Hàng Xanh') ORDER BY id ASC LIMIT 1) s ON TRUE WHERE LOWER(r.name) = LOWER('TP. Hồ Chí Minh - Đà Lạt')   AND NOT EXISTS (    SELECT 1 FROM trip_stops x WHERE x.trip_id = t.id AND x.station_id = s.id AND x.stop_type = 'pickup'  );
